import { Component } from '@angular/core';
import { ChipComponent } from './chip.component';

@Component({
  selector: 'app-demo',
  imports: [ChipComponent],
  template: `<dma-chip [kind]="kind">{{ label }}</dma-chip>`,
})
export class DemoComponent {
  kind = 'neutral';
  label = 'Label';
}

